    #[tokio::test]
    async fn late_evaluation_does_not_dispatch_an_action() {
        struct Slow;
        #[async_trait(?Send)]
        impl Evaluator for Slow {
            async fn evaluate(&mut self, request: &Value, _: Duration) -> Result<Value, String> {
                tokio::time::sleep(Duration::from_millis(20)).await;
                Ok(answer(request, "Click", 0.0))
            }
        }
        let mut conf = config();
        conf["timeout"] = json!(1);
        let mut browser = MockBrowser::new();
        assert_eq!(
            execute(&conf, &mut browser, &mut Slow, &mut Journal::default())
                .await
                .0,
            "limit_reached"
        );
        assert!(browser.commands.is_empty());
    }

    #[tokio::test]
    async fn cancellation_preserves_in_flight_action_and_stops_loop() {
        struct PendingBrowser {
            dispatched: usize,
        }
        #[async_trait(?Send)]
        impl Browser for PendingBrowser {
            async fn command(
                &mut self,
                args: &[String],
                _: Option<&str>,
                _: Duration,
            ) -> Result<Value, String> {
                if args[0] == "snapshot" {
                    return Ok(json!({"success":true,"data":observation(0)}));
                }
                self.dispatched += 1;
                std::future::pending().await
            }
        }
        let mut browser = PendingBrowser { dispatched: 0 };
        let mut evaluator = MockEvaluator {
            choices: VecDeque::from([("Fill", 0.0)]),
        };
        let mut journal = Journal::default();
        let outcome = tokio::time::timeout(
            Duration::from_millis(10),
            execute(&config(), &mut browser, &mut evaluator, &mut journal),
        )
        .await;
        assert!(outcome.is_err());
        assert_eq!(browser.dispatched, 1);
        assert_eq!(journal.steps[0]["outcome"], "unknown");
    }

    #[tokio::test]
    async fn gateway_protocol_and_provider_error_redaction() {
        use tokio::io::{AsyncReadExt, AsyncWriteExt};
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
        let url = format!(
            "http://{}/v4/ai/evaluation-model",
            listener.local_addr().unwrap()
        );
        let server = tokio::spawn(async move {
            let (mut stream, _) = listener.accept().await.unwrap();
            let mut bytes = vec![0; 8192];
            let n = stream.read(&mut bytes).await.unwrap();
            let request = String::from_utf8_lossy(&bytes[..n]).to_lowercase();
            assert!(request.starts_with("post /v4/ai/evaluation-model "));
            assert!(request.contains("ai-model-id: typesafe-ai/jev"));
            assert!(request.contains("ai-evaluation-model-specification-version: 4"));
            assert!(request.contains("ai-gateway-protocol-version: 0.0.1"));
            let body = r#"{"error":{"message":"echoed-secret-key"}}"#;
            stream.write_all(format!("HTTP/1.1 403 Forbidden\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",body.len()).as_bytes()).await.unwrap();
        });
        let mut evaluator = GatewayEvaluator {
            client: reqwest::Client::new(),
            url,
            key: "echoed-secret-key".into(),
            model: DEFAULT_MODEL.into(),
        };
        let error = evaluator
            .evaluate(
                &json!({"state":"test","questions":{}}),
                Duration::from_secs(3),
            )
            .await
            .unwrap_err();
        server.await.unwrap();
        assert!(error.contains("403"));
        assert!(!error.contains("echoed-secret-key"));
    }

